def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    stamp = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]

    if not stamp:
        return out

    r0, r1 = min(r for r, c in stamp), max(r for r, c in stamp)
    c0, c1 = min(c for r, c in stamp), max(c for r, c in stamp)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    pattern = [(r - ar, c - ac, grid[r][c]) for r, c in stamp]

    for mr, mc in markers:
        for dr, dc, value in pattern:
            rr, cc = mr + dr, mc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value

    return out
